import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`team member: view the graph visually with documents as nodes and links as edges`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the graph view displays every document as a node and every link as a connection, updating live as documents and links are added or removed`, async ({ page }) => {
    // Create a document so the graph has at least one node
    await page.getByRole('button', { name: '+ New' }).click();
    await page.getByPlaceholder('Document title…').fill('Graph Node Doc');
    await page.getByRole('button', { name: 'Create' }).click();
    await expect(page.getByPlaceholder('add tag…')).toBeVisible({ timeout: 10_000 });

    // Switch to Graph view using the sidebar view switcher
    await page.getByRole('button', { name: 'Graph' }).click();

    // The canvas (force-directed graph rendering surface) is visible
    await expect(page.locator('canvas')).toBeVisible({ timeout: 5_000 });

    // The stats counter in the bottom-right reflects at least 1 node
    // GraphVisualizationView renders: "{count} node(s) · {count} link(s)"
    await expect(page.getByText(/\d+ node/)).toBeVisible({ timeout: 5_000 });

    // Create a second document while in Graph view — graph updates live
    await page.getByRole('button', { name: '+ New' }).click();
    await page.getByPlaceholder('Document title…').fill('Graph Node Doc 2');
    await page.getByRole('button', { name: 'Create' }).click();

    // Switch back to Graph view (creating a doc auto-switches to list/detail)
    await page.getByRole('button', { name: 'Graph' }).click();

    // Stats counter now shows 2 nodes
    await expect(page.getByText(/2 nodes/)).toBeVisible({ timeout: 10_000 });
  });
});
